import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel (fp16 matrix multiplication) and PyTorch bindings
# ----------------------------------------------------------------------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE 16  // 16x16 threads per block, tile size 16

// ------------------------------------------------------------------
// Kernel: C = A * B   (all matrices are N x N, stored row‑major)
// A, B, C are half (fp16). Accumulation is done in float for accuracy.
// ------------------------------------------------------------------
extern "C" __global__
void matmul_fp16_kernel(const half* __restrict__ A,
                        const half* __restrict__ B,
                        half* __restrict__ C,
                        const int N) {
    // thread identifiers
    const int tx = threadIdx.x;   // [0, TILE)
    const int ty = threadIdx.y;   // [0, TILE)
    const int row = blockIdx.y * TILE + ty;
    const int col = blockIdx.x * TILE + tx;

    __shared__ half As[TILE][TILE];
    __shared__ half Bs[TILE][TILE];

    float acc = 0.0f;

    // loop over tiles of K dimension
    for (int t = 0; t < N; t += TILE) {
        // load one tile of A and B into shared memory
        if (row < N && (t + tx) < N)
            As[ty][tx] = A[row * N + t + tx];
        else
            As[ty][tx] = __float2half(0.0f);

        if (col < N && (t + ty) < N)
            Bs[ty][tx] = B[(t + ty) * N + col];
        else
            Bs[ty][tx] = __float2half(0.0f);

        __syncthreads();

        // compute partial product for this tile
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[ty][k]) * __half2float(Bs[k][tx]);
        }

        __syncthreads();
    }

    // write result
    if (row < N && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// Launcher (exposed to Python)
// ------------------------------------------------------------------
void matmul_fp16_launcher(torch::Tensor A,
                          torch::Tensor B,
                          torch::Tensor C) {
    const int N = A.size(0);
    const dim3 block(TILE, TILE);
    const dim3 grid((N + TILE - 1) / TILE,
                    (N + TILE - 1) / TILE);

    // sanity checks (all tensors must be contiguous, same shape, fp16)
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous() && C.is_contiguous(),
                "All tensors must be contiguous");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16 &&
                C.dtype() == torch::kFloat16,
                "All tensors must be float16");
    TORCH_CHECK(A.sizes() == B.sizes() && A.sizes() == C.sizes(),
                "All tensors must have the same shape");
    TORCH_CHECK(A.dim() == 2 && A.size(0) == A.size(1),
                "Only square 2‑D matrices are supported");

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        A.scalar_type(), "matmul_fp16_launcher", ([&] {
            matmul_fp16_kernel<<<grid, block>>>(
                reinterpret_cast<const half*>(A.data_ptr()),
                reinterpret_cast<const half*>(B.data_ptr()),
                reinterpret_cast<half*>(C.data_ptr()),
                N);
        })
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch failed: ") + cudaGetErrorString(err));
    }
}

// ------------------------------------------------------------------
// PyBind11 module definition
// ------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16_launcher, "FP16 matrix multiplication (A100)");
}
'''

# Compile the extension inline
matmul_ext = load_inline(
    name='matmul_fp16_ext',
    cpp_sources='',
    cuda_sources=src,
    functions=['matmul_fp16'],
    verbose=False,
)

# ----------------------------------------------------------------------
# Autograd Function that wraps the custom kernel
# ----------------------------------------------------------------------
class MatMulFP16Function(torch.autograd.Function):
    @staticmethod
    def forward(ctx, A, B):
        # Ensure inputs are fp16, contiguous and on CUDA
        A = A.to(torch.float16).contiguous()
        B = B.to(torch.float16).contiguous()
        C = torch.empty_like(A, dtype=torch.float16, device='cuda')
        matmul_ext.matmul_fp16(A, B, C)
        return C

    @staticmethod
    def backward(ctx, grad_output):
        # Gradient w.r.t. inputs can be expressed via matmul as well
        # dL/dA = grad_output @ B^T
        # dL/dB = A^T @ grad_output
        grad_output = grad_output.to(torch.float16).contiguous()
        # Use the same custom kernel for the two products
        grad_A = MatMulFP16Function.apply(grad_output, B.t())
        grad_B = MatMulFP16Function.apply(A.t(), grad_output)
        return grad_A, grad_B

# ----------------------------------------------------------------------
# ModelNew: drop‑in replacement for the reference Model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Same API as the reference Model but uses a custom fp16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return MatMulFP16Function.apply(A, B)
